const fs=require('fs'),path=require('path');const root='/harness-state/.gbrain/content/51e1b4cb-d921-48e7-bbce-0cf61b40541d/default';
const dirs={people:['Individual humans; one canonical page per person.','Organizations belong in companies; specific encounters in meetings.'],companies:['Organizations and institutions.','Individuals belong in people; bounded work in projects.'],concepts:['Reusable ideas, mental models and technical concepts.','Active work belongs in projects; unresolved captures in inbox.'],projects:['Bounded work with an outcome, owner or specification.','Organizations belong in companies; reusable knowledge in concepts.'],meetings:['Specific dated meetings and their evidence.','Ongoing entity summaries belong in people or companies.'],sources:['Raw source documents and provenance references.','Derived summaries belong in the appropriate entity or concept folder.'],inbox:['Temporary captures awaiting classification.','Classified knowledge belongs in its primary directory.'],archive:['Inactive knowledge retained as historical evidence.','Active facts belong in their primary directory.']};
function create(rel,text){const f=path.join(root,rel);try{fs.writeFileSync(f,text,{flag:'wx',mode:0o600});console.log('Created '+rel)}catch(e){if(e.code"'!=='"'EEXIST')throw e;console.log('Preserved '+rel)}}
for(const [dir,[yes,no]] of Object.entries(dirs)){fs.mkdirSync(path.join(root,dir),{recursive:true,mode:0o700});create(dir+'/README.md',"'`# ${dir}'"\\n\\nWhat goes here: "'${yes}'"\\n\\nOther homes: "'${no}'"\\n"'`)}
create('"'RESOLVER.md','# Brain filing resolver\\n\\nRead this before creating a brain page. Find existing records with GBrain first; update the canonical page instead of duplicating it.\\n\\n'+Object.entries(dirs).map(([dir,[yes]],i)=>"'`${i+1}. ${dir}/ — ${yes}`).join('"'\\n')+'\\n\\nOne primary home per entity. Cross-link related pages. Check each directory README for distinctions. Uncertain captures go in inbox/. This resolver organizes memory; it does not authorize automatic saving, imports, paid enrichment or identity changes.\\n');
create('schema.md','# Memory page conventions\\n\\nUse YAML frontmatter with a title and an active-schema page type. Use canonical lowercase hyphenated slugs. Begin with a current summary; cite factual statements with their source and date. Separate current compiled truth from an append-only, dated Timeline with a horizontal rule. Cross-link existing entities and maintain backlinks. Do not invent user facts. Save only explicitly requested facts unless automatic saving is enabled.\\n\\nSkill dispatcher: /harness-state/.bun/install/global/node_modules/gbrain/skills/RESOLVER.md. Read only the relevant skill. Runtime memory settings and Codex wiring stay in local configuration, not user facts.\\n');
JS"

